Translate("deDE", "blackfathom-deeps", {
	title = "Blackfathom-Tiefe",
	aliases = { "Blackfathom" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Blackfathom-Tiefe ist ein versunkener Tempel unter der Küste von {link:ashenvale}Eschental{/link}, am {link:the-zoram-strand}Zoramstrand{/link}. Ein von alten Treppen gesäumter Schacht fällt vom Ufer hinab in dunkles Wasser, und der Weg hinein muss geschwommen werden. Dahinter liegen überflutete Höhlen, zerbrochene Schreine und versunkene Hallen aus hellem elfischem Stein. Einst war dies ein heiliger Ort der Mondgöttin Elune. Nun gehört er dem {link:twilight-s-hammer}Schattenhammer{/link}, den {link:naga}Naga{/link} und den {link:satyrs}Satyrn{/link}, die an ihrer Seite dienen, und dem Wesen, das sie im tiefsten Becken verehren: der Hydra {link:aku-mai}Aku'mai{/link}.]=],
		},
		{
			title = "Ursprünge",
			text = [=[Im Zeitalter vor der {link:great-sundering}Großen Zerschlagung{/link} errichteten die {link:night-elves}Nachtelfen{/link} an der Westküste des alten {link:kalimdor}Kalimdor{/link} einen großen Tempel für Elune. Es steht geschrieben, dass {link:queen-azshara}Königin Azshara{/link} selbst seinen Bau überwachte. In seinem Herzen lag ein Mondbrunnen. Als die Zerschlagung die Welt zerriss, zerbrach der Tempel und sank unter die Wellen, und für Zeitalter lag er verloren und still. Doch schon damals barg er nicht nur Heiliges. Ein Elf namens Lorgalis, ein Anbeter der {red:old-gods}Alten Götter{/red}, hinterließ in seinen Mauern ein Manuskript zu ihrem Lob, und es wurde nie vernichtet.

In späteren Tagen sickerte eine Verderbnis der Alten Götter aus der Tiefe der Erde empor und besudelte den heiligen Mondbrunnen. {link:aku-mai}Aku'mai{/link}, eine Dienerin jener uralten Mächte, erhob sich aus den Wassern und machte die Ruinen zu ihrem Hort.]=],
		},
		{
			title = "Die heutige Zeit",
			text = [=[Der {link:twilight-s-hammer}Schattenhammer{/link} ist in die Tiefe gekommen, um die Hydra zu verehren. Seine Kultisten stammen aus vielen Völkern, {link:humans}Menschen{/link} und {link:orcs}Orcs{/link}, {link:trolls}Trolle{/link}, {link:tauren}Tauren{/link} und sogar {link:forsaken}Verlassene{/link}, alle vereint durch ihren Glauben an die Rückkehr der Alten Götter. Angeführt von {link:twilight-lord-kelris}Schattenfürst Kelris{/link} opfern sie {link:aku-mai}Aku'mai{/link} Unschuldige im Tausch gegen Macht. Die {link:naga}Naga{/link} des Stammes Blackfathom haben sich ihnen angeschlossen, und {link:satyrs}Satyrn{/link} der Fallenroot spuken in den Tunneln. Die Naga ernten Saphire aus den Höhlenwänden, denn die Geister des Wassers haften an diesen Steinen.

Die Welt dort oben ist aufmerksam geworden. Die {link:argent-dawn}Argentumdämmerung{/link} in {link:darnassus}Darnassus{/link} sandte einen Späher aus, um den Tempel zu beobachten, und er kehrte nicht zurück. Der {link:earthen-ring}Irdene Ring{/link} schickte den Troll {link:je-neu-sancrea}Je'neu Sancrea{/link} an den {link:the-zoram-strand}Zoramstrand{/link}, um zu erfahren, was der Kult den Elementen antut. {link:gershala-nightwhisper}Gershala Nightwhisper{/link} aus {link:auberdine}Auberdine{/link} will für ihre Studien die Gehirne der verderbten Naga und Satyrn, und {red:gerrig-bonegrip}Gerrig Bonegrip{/red} aus {link:ironforge}Ironforge{/link} begehrt das Manuskript des Lorgalis.]=],
		},
		{
			title = "In der Tiefe",
			text = [=[• {b}Der ertrunkene Eingang.{/b} Treppen und überflutete Gänge führen vom Ufer hinab. Saphirhaufen glitzern an den Wänden, und Priesterinnen der {link:naga}Naga{/link} sammeln sie.
• {b}Das Becken von Ask'ar.{/b} Eine große überflutete Höhle mit einer Insel in der Mitte, auf der die wahnsinnige Schildkröte {link:ghamoo-ra}Ghamoo-ra{/link} umherstreift. Der verwundete Späher {link:argent-guard-thaelrid}Thaelrid{/link} verbirgt sich in ihrer Nähe. In einer Seitenbucht hält die Seehexe {link:lady-sarevess}Lady Sarevess{/link} ihren eigenen Hof.
• {b}Der Schrein von {link:gelihast}Gelihast{/link}.{/b} Hier versammeln sich die {link:murlocs}Murlocs{/link} der Blindlight um ihren Häuptling und seinen Altar.
• {b}Die Ruinen des Mondschreins.{/b} Die zerbrochenen Hallen des alten Tempels, halb unter Wasser, in denen die Kultisten ihre Lager halten. Ein Tiefenstein liegt im Wasser, und etwas Elementares bewacht ihn.
• {b}Das vergessene Becken.{/b} Unter den Ruinen eine ertrunkene Höhle, in der ein uralter Drescher lebt, der nie gefangen wurde.
• {b}Das Sanktum des Mondschreins.{/b} Hier sitzt {link:twilight-lord-kelris}Schattenfürst Kelris{/link} in Trance vor dem Altar der Alten Götter.
• {b}Aku'mais Hort.{/b} Hinter den versiegelten Türen des Sanktums liegt das tiefste Becken, in dem die Hydra wartet.]=],
		},
	},
})

Translate("deDE", "lorgalis-manuscript", {
	title = "Lorgalis-Manuskript",
	found = "Eine narbige Eisentruhe in den Tiefen der Blackfathom-Tiefe",
	sections = {
		{
			title = "Anmerkungen",
			text = [=[Eine kurze Schrift zum Lob der {red:old-gods}Alten Götter{/red}, von einem Elfen namens Lorgalis im versunkenen Tempel zurückgelassen. Der Verfasser nennt die Alten Götter die ersten Herren der Welt, nun gekettet und schlafend, und lehrt, dass nur jene Gunst finden, die vor ihren Dienern knien. Die letzte Seite nennt {link:aku-mai}Aku'mai{/link} eine solche Dienerin und heißt sie die Prinzessin der Tiefe, die von älteren Sterblichen in den Tempel gebracht und dort als Zeichen des Göttlichen verehrt wurde. {red:gerrig-bonegrip}Gerrig Bonegrip{/red} aus {link:ironforge}Ironforge{/link} will das Manuskript abschreiben und unter seinen Brüdern und Schwestern verbreiten lassen.]=],
		},
	},
})

Translate("deDE", "aku-mai", {
	title = "Aku'mai",
	subtitle = "Prinzessin der Tiefe",
	found = "Aku'mais Hort, das tiefste Becken der Blackfathom-Tiefe",
	hint = [=[Suche das Wesen, das der Kult im tiefsten Becken der Blackfathom-Tiefe verehrt.]=],
	allegiance = "Die Alten Götter · verehrt vom Schattenhammer",
	aliases = { "Aku'Mai", "Prinzessin der Tiefe" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Aku'mai ist eine dreiköpfige Hydra von gewaltiger Größe, eine Dienerin der {red:old-gods}Alten Götter{/red}. Als die Verderbnis jener uralten Mächte in den Mondbrunnen des versunkenen Tempels sickerte, erhob sie sich aus seinen Wassern und machte die Ruinen zu ihrem Hort. Sie trägt einen Splitter der Stärke ihrer Herren in sich, und ihr Hunger nach lebendem Fleisch kennt kein Ende. Der {link:twilight-s-hammer}Schattenhammer{/link} verehrt sie als Zeichen, dass die Alten Götter zurückkehren werden, und nährt sie mit Opfern.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Aku'mai ist der Grund, warum der Kult in die {link:blackfathom-deeps}Blackfathom-Tiefe{/link} kam. Für den {link:twilight-s-hammer}Schattenhammer{/link} ist sie göttlich: ein Beweis, dass sich seine finsteren Schutzherren unter der Welt noch regen, und eine Quelle der Macht für alle, die ihr dienen. Die {link:naga}Naga{/link} sammeln in ihrem Namen die Saphire der Höhlen, und ihre Kultisten träumen von einem Tag, an dem sie die Herrschaft der Alten Götter nach {link:azeroth}Azeroth{/link} zurückbringt. Für die {link:argent-dawn}Argentumdämmerung{/link} und den Irdenen Ring ist sie eine eiternde Wunde an der Küste von {link:ashenvale}Eschental{/link}.]=],
		},
		{
			title = "Taten",
			text = [=[• Sie erhob sich aus dem besudelten Mondbrunnen des alten Tempels der Elune.
• Sie hat die Unschuldigen verschlungen, die der Kult ihr opfert.
• Bestien, die ihren Namen tragen, die Schnappkiefer und Fischer von Aku'mai, schwimmen in den Becken, und Wasserelementare dienen ihr.]=],
		},
	},
	chapters = {
		{
			title = "Prinzessin der Tiefe",
			hint = [=[Birg das alte Manuskript, das in den Tiefen des Tempels liegt.]=],
			text = [=[In den Tiefen lag eine Schrift, älter als der Kult, das Werk eines Elfen namens Lorgalis. Sie nannte Aku'mai die Prinzessin der Tiefe, eine Dienerin der Alten Götter, die im Tempel wohnte und seine Höhlen segnete. Ältere Sterbliche hätten sie dorthin gebracht, hieß es. Sie besaß nur einen Splitter der Macht ihrer Herren, und doch war er unermesslich. So wurde sie verehrt, gefürchtet und geliebt.]=],
		},
		{
			title = "Die Kristalle der Tiefe",
			hint = "Finde heraus, warum die Naga in den Höhlen Saphire sammeln.",
			text = [=[Man sah die {link:naga}Naga{/link} die großen Saphire der Höhlen ernten, und {link:je-neu-sancrea}Je'neu Sancrea{/link} vom Irdenen Ring spürte die Geister des Wassers, die an ihnen hafteten. Eine zerknitterte Notiz, die man einer Priesterin der Naga abnahm, verriet den Rest. Die Kristalle wurden zu einem Anführer des Kults gebracht, um seinen Aquamanten bei ihren Beschwörungen zu helfen. Indem er ihre Macht meisterte, hoffte der Kult, Aku'mai zu besänftigen und sie eines Tages ganz hervorzurufen, um die Welt der Herrschaft der Alten Götter zurückzugeben.]=],
		},
	},
	mentions = {
		{
			text = [=[Schurkerei in der {link:blackfathom-deeps}Blackfathom-Tiefe{/link}]=],
		},
		{ text = "Die Essenz von Aku'Mai" },
	},
	bonds = {
		{ id = "twilight-lord-kelris", name = "Schattenfürst Kelris", note = "ihr Hohepriester" },
		{ id = "lorgus-jett", name = "Lorgus Jett", note = "suchte sie zu besänftigen" },
		{ id = "lady-sarevess", name = "Lady Sarevess", note = "dient dem Kult, der sie verehrt" },
	},
})

Translate("deDE", "twilight-lord-kelris", {
	title = "Schattenfürst Kelris",
	subtitle = "Fürst des Schattenhammers in der Tiefe",
	found = "Das Sanktum des Mondschreins, vor dem Altar der Alten Götter",
	hint = [=[Suche den Meister des Kults im Sanktum des versunkenen Tempels.]=],
	allegiance = "Schattenhammer",
	aliases = { "Kelris" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Schattenfürst Kelris führt den {link:twilight-s-hammer}Schattenhammer{/link} in der {link:blackfathom-deeps}Blackfathom-Tiefe{/link} an. Er sitzt in Trance im Sanktum des alten Tempels, neben dem Altar, an dem der Kult seine Opfer darbringt. Unter seiner Herrschaft opfern die Kultisten der Hydra {link:aku-mai}Aku'mai{/link} Unschuldige und erhalten dafür Macht. Kelris gebietet über die Magie der Schatten und des Schlafes, und im Kampf kann er seine Feinde in einen hilflosen Schlummer versetzen.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Lange Zeit entzog sich Kelris der {link:argent-dawn}Argentumdämmerung{/link}. Ihre {link:the-night-watch}Wächter{/link} in {link:darnassus}Darnassus{/link} sagen, dass er jedes Mal seine Hand im Spiel hatte, wenn sich in diesen Landen das Böse zeigte, und jahrelang hielten sie ihn für tot oder verschollen. Er war weder das eine noch das andere. Er war in die Tiefe hinabgestiegen, um den {red:old-gods}Alten Göttern{/red} zu dienen, und er wollte die Welt in das Chaos ihres Zeitalters zurückführen. Die {link:tauren}Tauren{/link} von {link:thunder-bluff}Thunder Bluff{/link} nennen ihn ein Geschöpf des reinen Bösen.]=],
		},
		{
			title = "Taten",
			text = [=[• Er führte den {link:twilight-s-hammer}Schattenhammer{/link} in den versunkenen Tempel der Elune.
• Er verbündete den Kult mit den {link:naga}Naga{/link} der {link:blackfathom-deeps}Blackfathom{/link}.
• Er opferte {link:aku-mai}Aku'mai{/link} Unschuldige im Tausch gegen Macht.]=],
		},
	},
	chapters = {
		{
			title = "Der Bericht des Spähers",
			hint = [=[Finde den verschollenen Späher der Argentumdämmerung in der Tiefe.]=],
			text = [=[Die {link:argent-dawn}Argentumdämmerung{/link} sandte einen Späher aus, um den Tempel zu beobachten, und Wochen vergingen ohne Nachricht. Als man ihn endlich fand, lag er verwundet in den Höhlen, seine Kraft war dahin. Er hatte erfahren, was der Kult trieb. Der {link:twilight-s-hammer}Schattenhammer{/link} und die {link:naga}Naga{/link} hielten die Ruinen gemeinsam, und ihr Anführer Kelris fütterte die Hydra mit Unschuldigen, um Macht zu gewinnen. Der Späher konnte nichts weiter tun. Er bat darum, Kelris zu erschlagen und seinen Kopf aus der Tiefe zu tragen.]=],
		},
		{
			title = "Der Kopf des Kelris",
			hint = "Beende die Herrschaft des Schattenfürsten.",
			text = [=[Als der Kopf des Kelris der {link:argent-dawn}Argentumdämmerung{/link} in {link:darnassus}Darnassus{/link} gebracht wurde, sagte Dämmerwächter Selgorm, nun ergebe endlich alles einen Sinn: Der Mann, den sie für tot gehalten hatten, hatte die ganze Zeit hinter dem Bösen gesteckt. Bei der {link:horde}Horde{/link} dankte Bashana Runetotem der Erdenmutter und sagte, einen anderen zum eigenen Vorteil einem Diener der Alten Götter zu opfern, sei mit Worten nicht zu fassen. Durch seinen Tod wurden viele unschuldige Leben verschont.]=],
		},
	},
	mentions = {
		{ text = "Der Fall des Schattenhammers" },
		{
			text = [=[Schurkerei in der {link:blackfathom-deeps}Blackfathom-Tiefe{/link}, der Kopf nach {link:darnassus}Darnassus{/link} gebracht]=],
		},
		{
			text = [=[Schurkerei in der {link:blackfathom-deeps}Blackfathom-Tiefe{/link}, der Kopf nach {link:thunder-bluff}Thunder Bluff{/link} gebracht]=],
		},
	},
	bonds = {
		{ id = "aku-mai", name = "Aku'mai", note = "die Macht, der er dient" },
		{ id = "argent-guard-thaelrid", name = "Argentumwache Thaelrid", note = "der Späher, der ihn enttarnte" },
		{ id = "lorgus-jett", name = "Lorgus Jett", note = "ein Diener desselben Kults" },
	},
})

Translate("deDE", "argent-guard-thaelrid", {
	title = "Argentumwache Thaelrid",
	subtitle = "Späher der Argentumdämmerung",
	found = [=[Die Höhlen nahe dem Becken von Ask'ar, in der Blackfathom-Tiefe]=],
	hint = [=[Suche den verschollenen Späher der Argentumdämmerung in den überfluteten Höhlen der Blackfathom-Tiefe.]=],
	allegiance = "Argentumdämmerung · Nachtelfen",
	aliases = { "Thaelrid" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Argentumwache Thaelrid ist ein {link:night-elves}Nachtelf{/link} der {link:argent-dawn}Argentumdämmerung{/link}. {red:dawnwatcher-shaedlass}Dämmerwächterin Shaedlass{/red} schickte ihn von {link:darnassus}Darnassus{/link} aus, um den {link:twilight-s-hammer}Schattenhammer{/link} und die {link:naga}Naga{/link} in der {link:blackfathom-deeps}Blackfathom-Tiefe{/link} zu beobachten. Er erfuhr ihr Geheimnis, doch er wurde verwundet und konnte nicht zurückkehren. Er wartet in den Höhlen, zu schwach, um weiterzugehen, und bittet jene, die ihn finden, zu vollenden, was er nicht vermochte: {link:twilight-lord-kelris}Schattenfürst Kelris{/link} zu erschlagen.]=],
		},
	},
	chapters = {
		{
			title = "Ein finsterer Plan",
			hint = "Folge dem Ruf der Argentumdämmerung und suche ihren Späher.",
			text = [=[Wochen nachdem er in die Tiefe gegangen war, fand man Thaelrid lebend. Shaedlass habe zu Recht Sorge gehabt, sagte er. An diesem verderbten Ort sei ein finsterer Plan im Gange.]=],
		},
	},
	mentions = {
		{
			text = [=[Schurkerei in der {link:blackfathom-deeps}Blackfathom-Tiefe{/link}]=],
		},
	},
	bonds = {
		{ id = "twilight-lord-kelris", name = "Schattenfürst Kelris", note = "der Feind, den er enttarnte" },
	},
})

Translate("deDE", "morridune", {
	title = "Morridune",
	subtitle = "Der reuige Kultist",
	found = "Aku'mais Hort, nach dem Fall der Hydra",
	hint = [=[Suche den, der darauf wartete, aus dem Hort der Hydra befreit zu werden.]=],
	allegiance = "Einst der Schattenhammer · Darnassus",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Morridune ist ein {link:dwarves}Zwerg{/link} aus Khaz Modan, der einst dem {link:twilight-s-hammer}Schattenhammer{/link} folgte. Er kam, besessen von den {red:old-gods}Alten Göttern{/red}, in die Tiefe und hoffte, Macht aus {link:aku-mai}Aku'mai{/link} zu schöpfen. Dann sah er, wie der Kult unzählige Unschuldige opferte, und kam zur Besinnung. Dafür wurde er im Hort der Hydra gefangen gesetzt. Als Aku'mai starb, rief er, dass er nun endlich gehen könne. Aus Dankbarkeit öffnet er den Bezwingern der Hydra, die Freunde der {link:alliance}Allianz{/link} sind, einen Weg nach {link:darnassus}Darnassus{/link}.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Morridune ist der Beweis, dass manche, die dem Hammer verfallen, umkehren können.]=],
		},
	},
	bonds = {
		{ id = "aku-mai", name = "Aku'mai", note = "die Bestie, der er einst dienen wollte" },
	},
})

Translate("deDE", "ghamoo-ra", {
	title = "Ghamoo-ra",
	subtitle = "Die gequälte Schildkröte",
	found = "Die Insel im Becken von Ask'ar",
	hint = [=[Stelle dich der großen Schildkröte, die über die Insel in der überfluteten Höhle streift.]=],
	allegiance = "Schattenhammer",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Ghamoo-ra ist eine riesige Schildkröte des versunkenen Tempels. Es heißt, er sei eines der letzten friedlichen Geschöpfe gewesen, die dort lebten, als der {link:twilight-s-hammer}Schattenhammer{/link} eintraf. Die Kultisten weckten ihn und legten ihn in Ketten. Jahrelang quälten sie ihn an Leib und Geist, bis er wahnsinnig wurde. Sie gaben ihm seinen Namen und richteten ihn ab, jeden Fremden anzugreifen, der sich ihrem Schrein näherte. Nun zertrampelt er alle, die seine Insel betreten, während kleinere Schildkröten um ihn herumschwimmen.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Ghamoo-ra ist der erste {link:the-night-watch}Wächter{/link} der Tiefe und die fleischgewordene Grausamkeit des Kults.]=],
		},
	},
	bonds = {
		{ id = "twilight-lord-kelris", name = "Schattenfürst Kelris", note = "der Herr seiner Peiniger" },
	},
})

Translate("deDE", "lady-sarevess", {
	title = "Lady Sarevess",
	subtitle = "Seehexe der Naga",
	found = "Eine Seitenbucht des Beckens von Ask'ar",
