	aliases = { "Sarevess" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Lady Sarevess ist eine Zauberin der {link:naga}Naga{/link}, eine verdrehte Herrin über Blitz und Frost. Es heißt, der {link:twilight-s-hammer}Schattenhammer{/link} habe ihr in der Tiefe eine eigene Bucht überlassen und schicke ihr immer neue Opfer. Im Gegenzug hoffen die Kultisten, dass ihre Riten ihnen eine Magie verleihen, die stark genug ist, um die Hydra zu verehren, ohne ihre nächste Mahlzeit zu werden. Eindringlinge empfängt sie mit dem Ruf an ihre Wachen, sie zu erschlagen.]=],
