	},
	bonds = {
		{ id = "aku-mai", name = "Aku'mai", note = "die Bestie, gegen die ihre Riten schützen sollen" },
		{ id = "twilight-lord-kelris", name = "Schattenfürst Kelris", note = "ihr Verbündeter im Kult" },
	},
})

Translate("deDE", "gelihast", {
	title = "Gelihast",
	subtitle = "Häuptling der Blindlight-Murlocs",
	found = "Der Schrein von Gelihast",
	hint = [=[Stelle dich dem Murlochäuptling, der in der Tiefe einen eigenen Schrein unterhält.]=],
	allegiance = "Blindlight-Murlocs",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Gelihast ist der Häuptling der Blindlight-{link:murlocs}Murlocs{/link}, ein wilder Kämpfer mit Zwillingsklingen und Netzen. Es heißt, der Ruf der {red:old-gods}Alten Götter{/red} habe ihn in die Tiefe gelockt, und er habe sich den Weg hinein erzwungen, indem er fast ein Dutzend Kultisten des {link:twilight-s-hammer}Schattenhammers{/link} abschlachtete. Beeindruckt von seiner Wildheit ließ der Kult ihn bleiben. Er errichtete unter seinen Murlocs einen eigenen Schrein, und dort bringt er Opfer dar und empfängt die Segnungen der finsteren Gegenwart in den Ruinen.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Gelihast zeigt, wie die Alten Götter selbst die niedrigsten Geschöpfe des Meeres rufen.]=],
		},
	},
	bonds = {
		{ id = "aku-mai", name = "Aku'mai", note = "die Gegenwart, die er verehrt" },
	},
})

Translate("deDE", "lorgus-jett", {
	title = "Lorgus Jett",
	subtitle = "Diener des Schattenhammers",
	found = [=[Die Tunnel und Ruinen der Blackfathom-Tiefe, durch die er auf unvorhersehbaren Wegen geht]=],
	hint = "Jage den Kultisten, der die Saphire der Tiefe sammelt.",
	allegiance = "Schattenhammer",
	aliases = { "Lorgus" },
	sections = {
		{
			title = "Zusammenfassung",
