	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der alte Serra'kis ist ein gewaltiger Drescher, der in einer ertrunkenen Höhle unter den Ruinen lauert, wo es keine Luft zum Atmen gibt. Es heißt, als der {link:twilight-s-hammer}Schattenhammer{/link} kam, jagten die Kultisten die Geschöpfe der Gewässer als Nahrung, und die meisten von ihnen wurden gefressen. Serra'kis allein ließ sich nicht fangen. Wer ihn weiter jagte, starb bei dem Versuch. Er entzieht jedem das Leben, der ihm nahe kommt, und wird stärker, während sie schwächer werden. Nur wenige, die ihn im dunklen Wasser suchen, kehren zurück, um davon zu erzählen.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Serra'kis ist die letzte große Bestie in den Wassern des alten Tempels und die einzige Beute, die der Kult nie erlegte.]=],
